def solve():
    import sys
    T = int(sys.stdin.readline())
    for _ in range(T):
        S, P = sys.stdin.readline().split()
        if len(P) != 2 * len(S):
            print("Impossible")
            continue
        found = False
        for i in range(len(S) + 1):
            if P[:i] + P[i:] == S + S:
                found = True
                break
        print("Possible" if found else "Impossible")

solve()
